export const ROOMS={
 block:{name:'The Neon Strip',label:'01 / FIRST IMPRESSIONS',color:'#a879ff',description:'Midnight. Your outfit says VIP. Your bank balance says complimentary tap water. Somewhere above the city, a rooftop party is missing its headline act.'},
 diner:{name:'The Last Bite',label:'02 / COFFEE & CONSEQUENCES',color:'#ffac72',description:'The diner smells like coffee and second chances. Bean has seen every bad pickup line in this city. Most were yours.'},
 shop:{name:'Off the Record',label:'03 / FIND YOUR FREQUENCY',color:'#79e9df',description:'DJ Vinyl fell asleep on the mixing desk. The speakers hum. His unfinished demo could save tonight’s rooftop show.'},
 club:{name:'The Velvet Rope',label:'04 / DRESSED FOR TROUBLE',color:'#f79cd0',description:'Brick guards the lift like it contains the last tennis ball on Earth. A mirror beside him offers an unsolicited style review.'},
 roof:{name:'Above the Noise',label:'05 / THE NIGHT IS YOURS',color:'#d6f991',description:'The city glitters below. Nova, a comedian with a sharper wit than your haircut, waits beside an empty stage. This night could still go several ways.'}
};
export const ITEMS={comb:{name:'Pocket comb',icon:'≋',description:'Nine teeth. More confidence than your last three outfits.'},flyer:{name:'Party flyer',icon:'▤',description:'Password: MOON. Soundcheck: MOON → BASS → BARK. Someone has very committed branding.'},token:{name:'Coffee token',icon:'◉',description:'Redeem at The Last Bite. The only currency your wallet is currently fluent in.'},coffee:{name:'Double espresso',icon:'☕',description:'Strong enough to reboot a DJ. Take it to Off the Record.'},vinyl:{name:'Unmixed record',icon:'◎',description:'DJ Vinyl’s track. Use the mixing desk in the record shop to finish it.'},demo:{name:'Midnight demo',icon:'♫',description:'A finished rooftop anthem. Now you need a wristband.'},pass:{name:'VIP wristband',icon:'∞',description:'Access to the rooftop. Proof that personal grooming sometimes works.'}};
export const ENDINGS={headliner:{title:'THE HEADLINER',score:1000,text:'You drop the Midnight Demo. The roof erupts. DJ Vinyl texts: “That’s my track!” You reply: “And our night.” For once, the city remembers you for the right reason.'},connection:{title:'AFTER THE AFTERPARTY',score:1250,text:'You leave the microphone to someone else and watch the sunrise with Nova. The conversation is easy. Nobody tries to sell anyone a vision board. She suggests breakfast. You suggest somewhere that accepts coffee tokens.'},flop:{title:'CERTIFIED PARTY ANIMAL',score:750,text:'Your microphone squeals. You freestyle a love song to a parking meter. The crowd laughs so hard the bartender drops a lime. By morning, you’re a meme. It is, technically, a form of fame.'}};
const allowedFlags=['flyer','token','awake','styled','password','mixed','pass','nova','kind','brag'];
export class StoryGame {
 constructor(saved=null){this.room='block';this.inventory=['comb'];this.flags={};this.mix=[];this.moves=0;this.topic=null;this.ending=null;this.speaker='THE NARRATOR';this.text=ROOMS.block.description;this.notice='';
  if(StoryGame.valid(saved)){this.room=saved.room;this.inventory=[...new Set(saved.inventory)];this.flags={...saved.flags};this.mix=[...saved.mix];this.moves=saved.moves;this.ending=saved.ending;this.text=saved.text;this.speaker=saved.speaker;}
 }
 static valid(s){return s?.version===1&&Object.hasOwn(ROOMS,s.room)&&Array.isArray(s.inventory)&&s.inventory.every(i=>Object.hasOwn(ITEMS,i))&&s.flags&&typeof s.flags==='object'&&!Array.isArray(s.flags)&&Object.keys(s.flags).every(k=>allowedFlags.includes(k)&&typeof s.flags[k]==='boolean')&&Array.isArray(s.mix)&&s.mix.length<=3&&s.mix.every((v,i)=>v===['MOON','BASS','BARK'][i])&&Number.isInteger(s.moves)&&s.moves>=0&&(s.ending===null||Object.hasOwn(ENDINGS,s.ending))&&typeof s.text==='string'&&s.text.length<2000&&typeof s.speaker==='string'&&s.speaker.length<100;}
 has(id){return this.inventory.includes(id);}
 give(id){if(!this.has(id))this.inventory.push(id);}
 take(id){this.inventory=this.inventory.filter(i=>i!==id);}
 say(text,speaker='THE NARRATOR'){this.text=text;this.speaker=speaker;}
 go(room){if(!Object.hasOwn(ROOMS,room)||this.ending)return false;if(room==='roof'&&!this.flags.pass){this.say('The lift needs a VIP wristband. Brick at the Velvet Rope has the final word. Usually it’s “no.”');return false;}this.room=room;this.topic=null;this.notice='';this.say(ROOMS[room].description);return true;}
 use(item){if(!this.has(item)||this.ending)return false;this.moves++;this.topic=null;this.notice='';
  if(item==='comb'&&this.room==='club'){this.flags.styled=true;this.say('One flick of the comb. One adjustment of the cap. Brick nods. “Much better. Before, you looked like you lost a fight with a sofa.”','BRICK');this.notice='STYLE CHECK PASSED';}
  else if(item==='token'&&this.room==='diner'){this.take('token');this.give('coffee');this.say('“One double espresso. If your heart starts a podcast, stop drinking.” Bean slides the cup over.','BEAN');this.notice='DOUBLE ESPRESSO ACQUIRED';}
  else if(item==='coffee'&&this.room==='shop'){this.take('coffee');this.flags.awake=true;this.give('vinyl');this.say('“I wasn’t asleep. I was buffering.” Vinyl takes the coffee and hands you a record. “Finish the soundcheck and get this to the roof. The order is on the party flyer.”','DJ VINYL');this.notice='UNMIXED RECORD ACQUIRED';}
  else if(item==='vinyl'&&this.room==='shop'){this.topic='mixer';this.say('Three pads. One soundcheck. The flyer has the sequence. Your last attempt at DJing summoned a taxi.');}
  else if(item==='demo'&&this.room==='roof'){this.end('headliner');}
  else if(item==='pass'){this.go('roof');}
  else this.say(ITEMS[item].description,'YOUR POCKETS');
  return true;
 }
 hint(){if(!this.flags.token&&!this.has('coffee')&&!this.flags.awake)return 'Check the fountain on the Neon Strip. A coffee token is waiting there.';if(this.has('token'))return 'Take your token to the diner. Tap it in your pockets to order coffee.';if(this.has('coffee'))return 'DJ Vinyl needs that coffee. Visit Off the Record and tap the cup.';if(!this.flags.mixed)return 'Get the flyer on the Strip, then use the record at the mixing desk. MOON → BASS → BARK.';if(!this.flags.styled)return 'Visit the Velvet Rope and use your pocket comb at the mirror.';if(!this.flags.password)return 'Talk to Brick at the Velvet Rope. The password is on the flyer: MOON.';if(!this.flags.pass)return 'Show Brick you have the finished demo, the password, and some style.';return 'Take the lift to the roof. Play the demo, meet Nova, or risk the open mic. Three endings await.';}
 end(id){if(!Object.hasOwn(ENDINGS,id)||this.ending)return;this.ending=id;this.say(ENDINGS[id].text,ENDINGS[id].title);this.notice='CHAPTER COMPLETE';}
 actions(){const a=(id,label,detail,run)=>({id,label,detail,run});if(this.ending)return [];
  if(this.topic==='password')return [a('moon','“MOON.”','Keep it mysterious.',()=>{this.flags.password=true;this.topic=null;this.say('“Password checks out. Now: fresh look, finished demo. This is a party, not an onboarding seminar.”','BRICK');}),a('woof','“WOOF?”','A bold linguistic choice.',()=>{this.topic=null;this.say('“Wrong. Although that was my password in 2009.”','BRICK');}),a('famous','“Do you know who I am?”','Almost certainly not.',()=>{this.topic=null;this.say('“Yes. The guy without the password.”','BRICK');})];
  if(this.topic==='mixer')return ['MOON','BASS','BARK'].map(t=>a('mix-'+t,t,'Soundcheck pad',()=>{const order=['MOON','BASS','BARK'];if(t===order[this.mix.length]){this.mix.push(t);if(this.mix.length===3){this.flags.mixed=true;this.take('vinyl');this.give('demo');this.topic=null;this.notice='MIDNIGHT DEMO COMPLETE';this.say('The bass lands. The glass rattles. Vinyl grins. “That’s the one. Tell Brick I sent you.”','DJ VINYL');}else this.say(`${this.mix.join(' → ')}. The desk is warming up. What comes next?`,'SOUNDCHECK');}else{this.mix=[];this.say('The speakers make a noise like a fax machine falling downstairs. Start again: check the flyer.','SOUNDCHECK');}}));
  if(this.topic==='nova')return [a('listen','“What’s your story?”','Listen for once.',()=>{this.flags.kind=true;this.flags.nova=true;this.topic=null;this.say('“I write jokes about awkward dates. You’re either research or a very promising plot twist.” You talk. You listen. You somehow avoid mentioning your follower count.','NOVA');}),a('brag','“I’m kind of a big deal.”','The cap may be too tight.',()=>{this.flags.brag=true;this.flags.nova=true;this.topic=null;this.say('“Of course. Most big deals introduce themselves to a potted plant first.” She gestures to the fern you were leaning on.','NOVA');})];
  if(this.room==='block')return [a('poster','Read the flyer','A clue hiding in plain sight.',()=>{this.flags.flyer=true;this.give('flyer');this.say('ROOFTOP TONIGHT. Password: MOON. DJ soundcheck: MOON → BASS → BARK. Dress like you meant it.','THE FLYER');}),a('fountain',this.flags.token?'Check the fountain':'Search the fountain',this.flags.token?'Still suspiciously damp.':'Something glints beside the water.',()=>{if(!this.flags.token){this.flags.token=true;this.give('token');this.notice='COFFEE TOKEN ACQUIRED';this.say('A coffee token. Your fortune has doubled. Your fortune was previously one comb.');}else this.say('Just water now. You briefly consider starting a premium bottled-water brand.');}),a('promoter','Talk to Roxy','The promoter has a problem.',()=>this.say('“My DJ is asleep at Off the Record. The rooftop set is in trouble. Wake him up, finish his demo, and Brick will let you upstairs. Please don’t make this weird.”','ROXY'))];
  if(this.room==='diner')return [a('bean','Talk to Bean','The city’s most awake barista.',()=>this.say(this.has('token')?'“Coffee token? Now you’re speaking my language. Tap it in your pockets.”':this.has('coffee')?'“DJ Vinyl is waiting at the record shop. That coffee gets colder every time you try a line on me.”':'“The Strip fountain collects lost coins and questionable wishes. Try there.”','BEAN')),a('menu','Read the menu','Today’s special: consequences.',()=>this.say('ESPRESSO: one token. LIFE ADVICE: free. ACTUALLY TAKING IT: apparently too expensive.','THE MENU'))];
  if(this.room==='shop')return [a('vinyl','Talk to DJ Vinyl',this.flags.awake?'Genius. Allegedly.':'Currently in sleep mode.',()=>this.say(this.flags.mixed?'“Take that demo to Brick. And please credit the artist.”':this.flags.awake?'“Use the record at the desk. The flyer has the soundcheck order.”':'A tiny snore triggers the kick drum. This is either a medical miracle or a very niche genre.','DJ VINYL')),a('desk','Use the mixing desk','Three pads. One anthem.',()=>{if(!this.flags.awake)this.say('Vinyl is asleep on the power switch. Coffee first.');else if(this.flags.mixed)this.say('The demo is finished. Sometimes you have to know when to stop adding bass.');else{this.topic='mixer';this.mix=[];this.say('Soundcheck: three pads, in the order printed on the flyer.','THE MIXING DESK');}})];
  if(this.room==='club')return [a('mirror','Check the mirror','A brutally honest friend.',()=>this.say(this.flags.styled?'The look is working. You practice an entrance. The mirror charges no consulting fee.':'The hat is crooked. The fur is chaos. Your pocket comb has been training its whole life for this.')),a('brick','Talk to Brick','Wristbands, not excuses.',()=>{if(!this.flags.password){this.topic='password';this.say('“Password?”','BRICK');}else if(!this.flags.styled)this.say('“The password’s right. The hair is a cry for help. There’s a mirror. You own a comb. Work it out.”','BRICK');else if(!this.flags.mixed)this.say('“Looking sharp. Bring Vinyl’s finished demo and we’re good.”','BRICK');else{this.flags.pass=true;this.give('pass');this.notice='VIP WRISTBAND ACQUIRED';this.say('“Demo. Password. Actual grooming. Welcome upstairs. Please don’t lick the lift buttons.”','BRICK');}}),a('lift','Take the rooftop lift','The city is waiting.',()=>this.go('roof'))];
  return [a('nova','Talk to Nova','A conversation with possibilities.',()=>{this.topic='nova';this.say('“Nice entrance. I gave it an eight. Lost two points for checking your reflection in the fire extinguisher.”','NOVA');}),...(this.flags.brag&&!this.flags.kind?[a('apologize','“Okay. Let’s start over.”','Less ego. More honesty.',()=>{this.flags.kind=true;this.say('“Much better. I like the version of you that doesn’t need a press release.”','NOVA');})]:[]),a('play','Play the midnight demo','Make the whole roof move.',()=>this.end('headliner')),a('mic','Take the open mic','What could possibly go wrong?',()=>this.end('flop')),...(this.flags.kind?[a('sunrise','Catch the sunrise with Nova','Some nights need no encore.',()=>this.end('connection'))]:[])];
 }
 choose(id){const action=this.actions().find(a=>a.id===id);if(!action)return false;this.notice='';this.moves++;action.run();return true;}
 save(){return {version:1,room:this.room,inventory:[...this.inventory],flags:{...this.flags},mix:[...this.mix],moves:this.moves,ending:this.ending,text:this.text,speaker:this.speaker};}
}
